/* Compact gallery bundle: 30 distinct product photographs converted to WebP. */
(function () {
  "use strict";
  const encoded = {
    "amalfi-veranda-detail-1.jpg": "",
    "amalfi-veranda-detail-2.jpg": "",
    "anatolian-vintage-detail-1.jpg": "",
    "anatolian-vintage-detail-2.jpg": "",
    "atlas-berber-detail-1.jpg": "",
    "atlas-berber-detail-2.jpg": "",
    "bauhaus-geometric-detail-1.jpg": "",
    "bauhaus-geometric-detail-2.jpg": "",
    "caspian-silk-detail-1.jpg": "",
    "caspian-silk-detail-2.jpg": "",
    "isfahan-silk-detail-1.jpg": "",
    "isfahan-silk-detail-2.jpg": "",
    "jaipur-cotton-detail-1.jpg": "",
    "jaipur-cotton-detail-2.jpg": "",
    "kyoto-jute-detail-1.jpg": "",
    "kyoto-jute-detail-2.jpg": "",
    "manhattan-velvet-detail-1.jpg": "",
    "manhattan-velvet-detail-2.jpg": "",
    "moroccan-runner-detail-1.jpg": "",
    "moroccan-runner-detail-2.jpg": "",
    "nordic-geometric-detail-1.jpg": "",
    "nordic-geometric-detail-2.jpg": "",
    "oushak-runner-detail-1.jpg": "",
    "oushak-runner-detail-2.jpg": "",
    "santorini-outdoor-detail-1.jpg": "",
    "santorini-outdoor-detail-2.jpg": "",
    "scandinavian-cotton-detail-1.jpg": "",
    "scandinavian-cotton-detail-2.jpg": "",
    "solstice-jute-detail-1.jpg": "",
    "solstice-jute-detail-2.jpg": "",
  };
  const urls = Object.create(null);
  for (const [name, base64] of Object.entries(encoded)) {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    urls[name] = URL.createObjectURL(new Blob([bytes], { type: "image/webp" }));
  }
  window.RUG_GALLERY_IMAGES = urls;
})();
